  ('nimble', 'humanoid', 'Thorn Quickblade', '4', 'nimble-gmg-thorn-quickblade', 'official', 'Nimble GM''s Guide p. 46', '{"type":"Human Criminal","top":[["Armor","Medium"],["HP","125"]],"stats":[],"lines":[["Saves","DEX+"]],"sections":[{"title":"Traits","items":[{"n":"Strike Back","t":"When crit, make a Heart Piercer or Stormquill attack in return."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Stormquill (Crossbow)","t":"Move 4, 4d4+10 damage (Range 8)."},{"n":"Heart Piercer (Rapier)","t":"Move 8, 2d4+3 damage. On crit: Dazed."}]},{"title":"Bloodied","items":[{"n":"Smoke Bomb","t":"At 62 HP, Thorn immediately becomes invisible (until the end of his next turn), then moves 8, ignoring opportunity attacks."}]},{"title":"Last Stand","items":[{"n":"Mortal Panic!","t":"Thorn is dying! 30 more damage and he’s dead. Until then he’ll Strike Back EVERY time he’s hit (1/turn)."}]}],"hp":125}'::jsonb),
  ('nimble', 'monster', 'Ravager of the Lowlands', '5', 'nimble-gmg-ravager-of-the-lowlands', 'official', 'Nimble GM''s Guide p. 47', '{"type":"Manticore","size":"Large","top":[["Armor","Medium"],["HP","130"]],"stats":[],"lines":[["Saves","STR+ DEX+"]],"sections":[{"title":"Traits","items":[{"n":"Feral Instinct","t":"Whenever Ravager is crit, he can fly 10."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Venomous Stinger","t":"(1 use) Reach 3, 5d12 damage."},{"n":"Ravage","t":"Attack for 1d12+20 damage."},{"n":"Claw","t":"Fly 10, attack for 1d12+6 damage."}]},{"title":"Bloodied","items":[{"n":"At 65 HP","t":"His Venomous Stinger recharges."}]},{"title":"Last Stand","items":[{"n":"The Ravager is dying!","t":"40 more damage and he dies. Until then, the first time each turn he takes damage, he uses Move & Claw."}]}],"hp":130}'::jsonb),
  ('nimble', 'monster', 'Queen Aranya, Broodmother', '6', 'nimble-gmg-queen-aranya-broodmother', 'official', 'Nimble GM''s Guide p. 48', '{"type":"Matriarch of Spiders","size":"Large","top":[["Armor","Medium"],["HP","160"]],"stats":[],"lines":[["Saves","ALL+"]],"sections":[{"title":"Traits","items":[{"n":"Weave Web","t":"Creatures she hits are entangled in a sticky web (Dazed)."},{"n":"Flammable Webs","t":"Fire critical hits suppress Weave Web for 1 turn."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Impale","t":"(Reach 2) 2d8+8 damage. Then skitter away up to 8 spaces."},{"n":"Hatch Brood","t":"Summon spiderling minions (1/hero, size: d8); they act only when commanded."},{"n":"Dinner Time!","t":"Command all of your spiderling minions to move up to 6 spaces and attack once each."}]},{"title":"Bloodied","items":[{"n":"\"Avenge Your Queen, My Brood!\"","t":"At 80 HP, summon 3 spiderling minions/hero anywhere within Reach 8."}]},{"title":"Last Stand","items":[{"n":"Aranya is dying!","t":"40 more damage and she dies. Until then, Hatch Brood after each of her turns."}]}],"hp":160}'::jsonb),
  ('nimble', 'monster', 'Nalzar, Apex Predator', '6', 'nimble-gmg-nalzar-apex-predator', 'official', 'Nimble GM''s Guide p. 49', '{"type":"Grey Drake","size":"Large","top":[["Armor","Medium"],["HP","180"]],"stats":[],"lines":[["Saves","STR+ DEX+"]],"sections":[{"title":"Traits","items":[{"n":"Tail Swipe","t":"When dealt slashing or lightning damage: knock a hero within 3 spaces Prone."},{"n":"Torn Wings","t":"Each slashing crit reduces the Wing Buffet DC by 1."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Devour","t":"(Prone creatures only, Reach 2) 4d12+6."},{"n":"Wing Buffet","t":"Fly 8, then land. Cone 8: 1d12, then DC 14 STR save or also knocked Prone (advantage if behind cover or another hero)."}]},{"title":"Bloodied","items":[{"n":"At 90 HP","t":"Her Wing Buffet range and DC increase by 2."}]},{"title":"Last Stand","items":[{"n":"Nalzar is dying!","t":"60 more damage and she dies. Until then, each turn, she moves 6, then uses Devour (ignoring the Prone requirement)."}]}],"hp":180}'::jsonb),
  ('nimble', 'monster', 'Florindris, Bane of the Forest', '7', 'nimble-gmg-florindris-bane-of-the-forest', 'official', 'Nimble GM''s Guide p. 50', '{"type":"Floral Dragon","size":"Large","top":[["Armor","Medium"],["HP","200"]],"stats":[],"lines":[["Saves","ALL+"]],"sections":[{"title":"Traits","items":[{"n":"Aura of Wind","t":"Ranged attacks against you have disadvantage. End of turn: push adjacent creatures 2 spaces away."},{"n":"Wither","t":"Resistant to necrotic damage, but it suppresses Aura of Wind for 1 turn."},{"n":"Thornblight","t":"Suffer 5 damage for each space you are forcibly moved. Magical healing ends this effect."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Petal Storm","t":"(1 use) 3d10+10 damage to all enemies within Reach 8, half on a DC 13 DEX save."},{"n":"Rend","t":"Fly 10 before or after attacking. (Reach 2) 1d10+10 damage to up to 2 targets within reach. On hit: gain Thornblight."},{"n":"Gust","t":"(Reach 8) Move a target 1d10 spaces."}]},{"title":"Bloodied","items":[{"n":"At 100 HP","t":"Enemies within Reach 12 gain Thornblight, and Petal Storm recharges."}]},{"title":"Last Stand","items":[{"n":"Florindris is dying!","t":"70 more damage and she dies. Until then, Aura of Wind and Gust move creatures twice as far."}]}],"hp":200}'::jsonb),
  ('nimble', 'monster', 'General Flameheart', '8', 'nimble-gmg-general-flameheart', 'official', 'Nimble GM''s Guide p. 51', '{"type":"Flame Titan","size":"Huge","top":[["Armor","Heavy"],["HP","175"]],"stats":[],"lines":[["Saves","STR+ WIL+"]],"sections":[{"title":"Traits","items":[{"n":"Cinder Armor","t":"Immune to fire. When damaged, deal 5 fire damage to all adjacent creatures."},{"n":"Extinguish Flame","t":"Cold or radiant crits extinguish all areas ignited by Molten Fury and suppress Cinder Armor for 1 turn."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Inferno Cleave","t":"Move 8, then strike a 2×2 square area for 2d10+10 fire damage."},{"n":"Molten Fury","t":"Lob a molten fireball at the furthest hero not already in the flames, igniting a 2×2 square area. Creatures there take 2d10+10 damage, and another 10 damage at the end of each of their turns if they remain in the area."}]},{"title":"Bloodied","items":[{"n":"At 87 HP","t":"On his next turn, he uses Molten Fury a number of times equal to half the number of heroes (rounded up)."}]},{"title":"Last Stand","items":[{"n":"Flameheart is dying!","t":"80 more damage and he dies. Until then, the area of his attacks increases to a 3×3 square."}]}],"hp":175}'::jsonb),
  ('nimble', 'humanoid', 'Vael, Undying Necromancer', '9', 'nimble-gmg-vael-undying-necromancer', 'official', 'Nimble GM''s Guide p. 52', '{"type":"Luminary of Malice","top":[["Armor","None"],["HP","250"]],"stats":[],"lines":[["Saves","INT++ WIL++"]],"sections":[{"title":"Traits","items":[{"n":"Protect Master!","t":"Whenever Vael would fail a save or take 20 or more damage, he may sacrifice his Lifebinding Spirit, Bane, instead. He spends his next turn moving up to 6 spaces and summoning Bane."},{"n":"Actions","t":"After each hero’s turn, Bane attacks for 1d12+6, then Vael chooses one."}]},{"title":"Actions","items":[{"n":"DOOM","t":"(Range 12, undamaged target) DC 14 WIL save or 5d12 damage. Half on save."},{"n":"Veilwalker’s Rebuke","t":"(Range 8) 2d12+6. Double damage against those behind cover. 1/round you may swap places with them."},{"n":"Cruelty’s Edge","t":"1d4+2. On hit: DC 14 WIL save or Dazed and Frightened. Then move 6."}]},{"title":"Bloodied","items":[{"n":"Shield of Cruelty","t":"At 125 HP, Vael gains this reaction (1 use): if Vael would be damaged, instead he may reflect that much radiant damage back at the attacker."}]},{"title":"Last Stand","items":[{"n":"DEATH, AN OLD FRIEND","t":"Vael is dying! 90 more damage and he dies. Until then, he gains Heavy Armor, the hero that most recently damaged him is reduced to 0 HP, and Bane is sacrificed into a Vengeful Spirit. It deals 1d12+6 necrotic damage to creatures within Reach 3 at the end of each of his turns."}]}],"hp":250}'::jsonb),
  ('nimble', 'monster', 'Titan of the Deep Woods', '10', 'nimble-gmg-titan-of-the-deep-woods', 'official', 'Nimble GM''s Guide p. 53', '{"type":"Skeleton","size":"Gargantuan","top":[["Armor","Heavy"],["HP","240"]],"stats":[],"lines":[["Saves","STR+++"]],"sections":[{"title":"Traits","items":[{"n":"Splintering Legions","t":"Bludgeoning damage or any crit causes bones to splinter off and animate, forming a d10 minion."},{"n":"Brittle Bones","t":"Resistant to piercing, vulnerable to bludgeoning."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Devastating Strike","t":"(Reach 4) 1d4+30 damage. On hit: Knockback 6."},{"n":"Crushing Stomp","t":"Move up to 10 spaces. Deal 1d4+20 damage to up to 2 targets along the path. On hit: Prone."},{"n":"Beckoning Doom","t":"The 2 furthest heroes make a DC 16 STR save or are moved adjacent to Titan."}]},{"title":"Last Stand","items":[{"n":"Shattered Legion","t":"At 0 HP Titan collapses into 4 skeleton minions/hero (d10 sized). If any remain, they reassemble into the Titan the next evening."}]}],"hp":240}'::jsonb),
  ('nimble', 'monster', 'Ul’vek, Psionic Despot', '11', 'nimble-gmg-ulvek-psionic-despot', 'official', 'Nimble GM''s Guide p. 54', '{"type":"Brain-Eating Aberration","size":"Medium","top":[["Armor","None"],["HP","300"]],"stats":[],"lines":[["Saves","INT++ WIL++ DEX+"]],"sections":[{"title":"Traits","items":[{"n":"Mind Shield","t":"Whenever Ul’vek would fail a save or take more than 30 damage while he has a creature Dominated, he may avoid the attack instead, but all Dominated creatures come to their senses."},{"n":"Dominated","t":"Rolls are made with disadvantage. Ul’vek spends your first action on each of your turns: moving, making a weapon attack, or casting a cantrip. Damage ends."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Dominate","t":"(If no creatures are Dominated) Choose half of the heroes to suffer 2d12 psychic damage (ignoring armor). DC 15 WIL save or Dominated as well."},{"n":"Consume","t":"(Dominated creature) Contested DEX or STR check; on success: Grappled and 6d12. Cannot be Defended or Interposed against."},{"n":"Control","t":"Teleport 8. (Reach 8) DC 15 WIL save, or an enemy must spend one Action to make a weapon attack or cast a cantrip. On save, they attack with disadvantage."}]},{"title":"Bloodied","items":[{"n":"Illusory Shift","t":"At 150 HP, gain this reaction. When attacked (1 use): swap places with a Dominated creature, making them the new target of the attack."}]},{"title":"Last Stand","items":[{"n":"Ul’vek is dying!","t":"110 more damage and he dies. Until then, Dominated no longer ends on taking damage. Every hero makes a WIL save or becomes Dominated."}]}],"hp":300}'::jsonb),
  ('nimble', 'monster', 'Dravok, All-Seeing Tyrant', '12', 'nimble-gmg-dravok-all-seeing-tyrant', 'official', 'Nimble GM''s Guide p. 55', '{"type":"Aberration, all TEETH & EYES","size":"Large","top":[["Armor","None"],["HP","325"]],"stats":[],"lines":[["Saves","INT++ WIL++"]],"sections":[{"title":"Traits","items":[{"n":"My plans, flawless!","t":"Dravok makes all saves with +1 Advantage; attacks against him have Disadvantage."},{"n":"Weakness","t":"Taking more than 12 piercing or slashing damage: Dravok’s plans are FLAWED! (until the end of the next hero’s turn)."},{"n":"Actions","t":"After each hero’s turn, Move 6 and then use either Eye Ray (Range 10, randomly chosen ray, then choose target) or Terrible Maw."}]},{"title":"Actions","items":[{"n":"Terrible Maw","t":"Melee attack. 4d4, EVERY die can crit and is Vicious."},{"n":"Eye Ray 1: Warping Ray","t":"3d6. On hit: Dazed, exchange places with target."},{"n":"Eye Ray 2: Petrification Ray","t":"Permanently Dazed. Healing ends. (3 stacks: Petrified.)"},{"n":"Eye Ray 3: Terror Ray","t":"5d10 psychic damage & Terrified: you are Frightened, and your screams give allies within 6 disadvantage on rolls. Ends when Dravok’s plans are FLAWED."},{"n":"Eye Ray 4: Gravitation Ray","t":"2d6 damage. Push that many spaces. Knocked Prone on 7+."},{"n":"Eye Ray 5: Charm Ray","t":"DC 16 WIL save or Dravok spends 3 of your Actions attacking with or moving you, 2 Actions on save. (Cannot spend resources; you regain spent actions afterward.)"},{"n":"Eye Ray 6: Death Ray","t":"DC 16 STR save or drop to 0 HP. On save, gain 1 Wound. If a Dying creature fails this, they die."}]},{"title":"Bloodied","items":[{"n":"To Dust!","t":"At 110 HP, use Petrification Ray against every enemy. His save DC increases to 18."}]},{"title":"Last Stand","items":[{"n":"Dravok is dying!","t":"70 more damage and he dies. Until then, each turn he will move or use Warping Ray and then Devastation Beam: 2d12+20 in a 10 space long, 2 space wide line."}]}],"hp":325}'::jsonb),
  ('nimble', 'monster', 'Azriel, Lord of Pain & Flame', '14', 'nimble-gmg-azriel-lord-of-pain-flame', 'official', 'Nimble GM''s Guide p. 56', '{"type":"Balor","size":"Huge","top":[["Armor","Heavy"],["HP","320"]],"stats":[],"lines":[["Saves","ALL+"]],"sections":[{"title":"Traits","items":[{"n":"PAIN!","t":"Crits against Azriel are Vicious; he deals damage equal to the crit dice back to the attacker."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Crackling Whip","t":"Move 6. (Reach 6) 3d12 damage. On hit: Grappled and pulled adjacent to Azriel (escape DC 17 STR or DEX, or until he uses the whip again)."},{"n":"Doom Sword","t":"3d12+10 fire damage to all creatures within Reach 2."}]},{"title":"Bloodied","items":[{"n":"At 160 HP","t":"Azriel can use Crackling Whip twice each turn."}]},{"title":"Last Stand","items":[{"n":"YES, MORE PAIN!","t":"Azriel is dying! 180 more damage and he dies. Until then, EVERY hit against him is a crit."}]}],"hp":320}'::jsonb),
  ('nimble', 'monster', 'Gloomwing the Cruel', '15', 'nimble-gmg-gloomwing-the-cruel', 'official', 'Nimble GM''s Guide p. 57', '{"type":"Rot Dragon","size":"Huge","top":[["Armor","Heavy"],["HP","320"]],"stats":[],"lines":[["Saves","ALL++"]],"sections":[{"title":"Traits","items":[{"n":"Aura of Rot","t":"Creatures within 6 spaces take 5 necrotic damage at the end of their turns."},{"n":"Light Sensitivity","t":"Radiant damage suppresses Aura of Rot until the end of the next hero’s turn."},{"n":"Cruelty’s Gift","t":"Healing is halved and Vulnerable to necrotic damage. Healing ends."},{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Rot Breath","t":"(1 use) Fly 10, then (Cone 8) DC 17 DEX save or 8d10 necrotic, half on save."},{"n":"Bite","t":"(Reach 2) Move 6, then 3d10. On damage: Cruelty’s Gift."},{"n":"Claws","t":"(Reach 2) 3d10 slashing +10 necrotic."},{"n":"Tail","t":"(Reach 4) 1d10, and knocked back that many spaces."}]},{"title":"Bloodied","items":[{"n":"At 160 HP","t":"Gloomwing’s Rot Breath recharges."}]},{"title":"Last Stand","items":[{"n":"Gloomwing is dying!","t":"150 more damage and he dies. Until then, the damage and range of his Aura of Rot are doubled."}]}],"hp":320}'::jsonb),
  ('nimble', 'monster', 'Alaric Draegoth, the Crimson Count', '16', 'nimble-gmg-alaric-draegoth-the-crimson-count', 'official', 'Nimble GM''s Guide p. 58', '{"type":"Vampire Lord","top":[["Armor","None"],["HP","320"]],"stats":[],"lines":[["Saves","ALL++"]],"sections":[{"title":"Traits","items":[{"n":"Sanguine Cloak","t":"(1/turn) Deal 1d10 necrotic damage whenever you are hit; the attack is reduced by this amount."},{"n":"Sunscorn","t":"Vulnerable to radiant. After taking radiant damage, use Beguile as a Reaction; they roll with disadvantage."},{"n":"Beguiled","t":"Dazed. Cannot Defend or allow anyone to Interpose for you. Damage ends."},{"n":"Actions","t":"After each hero’s turn, summon 1 blood bat minion (d10) within 8 spaces, then choose one."}]},{"title":"Actions","items":[{"n":"Ebonfang","t":"Deal 1d10+15 damage; your target is considered Bloodied for 1 round. Fly 8 before or after attacking."},{"n":"Beguile","t":"If no creature is Beguiled, Beguile a target on a failed DC 18 WIL save (with disadvantage if Bloodied)."},{"n":"Beckon & Bite","t":"Move a Beguiled creature adjacent to you and bite them: 2d10+30 damage and 1 Wound."}]},{"title":"Bloodied","items":[{"n":"Mistform","t":"At 160 HP: no longer vulnerable to radiant. Bat Decoy: whenever Alaric would take damage, he first swaps places with a bat minion instead, 1/round."}]},{"title":"Last Stand","items":[{"n":"Alaric is dying!","t":"160 more damage and he dies. Until then, his Sanguine Cloak, attacks, and bats roll d20s instead of d10s."}]}],"hp":320}'::jsonb),
  ('nimble', 'monster', 'Caerys, the Hollow Star', '20', 'nimble-gmg-caerys-the-hollow-star', 'official', 'Nimble GM''s Guide p. 59', '{"type":"World-Ending Cataclysm, She Who Is Our Desire & End","top":[["Armor","Heavy"],["HP","620"]],"stats":[],"lines":[["Saves","ALL+++"]],"sections":[{"title":"Traits","items":[{"n":"Ravages of Time","t":"At the beginning of each round, all heroes suffer 1 Wound."},{"n":"Slipstream","t":"3/encounter: when she would suffer any negative effect, she can swap places with a creature of her choice, making them the target instead. All heroes recover 1 Wound."},{"n":"Actions","t":"After each hero’s turn, choose one not yet chosen (reset when all have been chosen)."}]},{"title":"Actions","items":[{"n":"Wormhole","t":"Teleport 12. 3d20 to a creature adjacent to where you began or ended."},{"n":"Immensity","t":"(Reach 12) DC 20 STR save (disadvantage if within Reach 4) or suffer 3d20 damage and Prone. Half on save."},{"n":"Glimpse Your End","t":"DC 20 WIL save or DOOMED: Concentration ends, the next damage roll against you is maximized."},{"n":"Plasma Storm","t":"Reach 6, DC 20 DEX save or 2d20 lightning and 2d20 fire damage. Half on save."},{"n":"Singularity","t":"Reach 2, 5d20 bludgeoning damage."},{"n":"Almighty Push & Pull","t":"(Range 12) DC 20 STR save or be launched 20 ft. into the air; repeat until the target saves. Fall damage for this attack is 1d20 for every 10 ft. fallen."}]},{"title":"Bloodied","items":[{"n":"Gravitational Mastery","t":"At 310 HP: move ALL objects and creatures within 16 spaces anywhere else within the area."},{"n":"Gravitational Lensing","t":"The hero with the most HP is marked by Caerys. She takes half damage from all sources, her mark takes the other half. This lasts until the mark drops to 0 HP."}]},{"title":"Last Stand","items":[{"n":"Caerys is dying!","t":"Use Gravitational Mastery, then Caerys is dying! 200 more damage and she dies. Until then she chooses twice each turn. If still alive after 1 round: Reset Time: she resets back to full HP."}]}],"hp":620}'::jsonb),
  ('nimble', 'monster', 'Krogg, Goblin King', '2', 'nimble-gmg-krogg-goblin-king', 'official', 'Nimble GM''s Guide p. 67', '{"type":"Angry Bugbear","top":[["Armor","Medium"],["HP","75"]],"stats":[],"lines":[["Saves","STR+ DEX+"]],"sections":[{"title":"Traits","items":[{"n":"Actions","t":"After each hero’s turn, choose one."}]},{"title":"Actions","items":[{"n":"Manglemaul","t":"Move 6. 2d6+3 damage, Grappled (escape DC 10). OR:"},{"n":"Crack Skulls","t":"Move 6. Swing a Grappled creature at another creature. Both take 2d6+3 damage, ending the Grapple."}]},{"title":"Bloodied","items":[{"n":"At 35 HP","t":"Krogg’s damage increases to 2d8+3."}]},{"title":"Last Stand","items":[{"n":"Krogg is dying!","t":"If he takes 20 more damage he dies. Until then, he has Heavy armor."}]}],"hp":75}'::jsonb),
  ('nimble', 'humanoid', 'Greenthumb, Lichling', '3', 'nimble-gmg-greenthumb-lichling', 'official', 'Nimble GM''s Guide p. 71', '{"type":"Botanical Wizard","top":[["Armor","None"],["HP","100"]],"stats":[],"lines":[["Saves","INT+ WIL+"]],"sections":[{"title":"Traits","items":[{"n":"Actions","t":"After each hero’s turn, move 6 and then choose one."}]},{"title":"Actions","items":[{"n":"Summon Briarbanes","t":"Summon 1 minion/hero (size: 1d4)."},{"n":"Root","t":"Choose half of the heroes to make a DC 11 DEX save or take 2d4 piercing damage and be Restrained by thorny vines (escape DC 11 STR or DEX save, or any slashing or fire damage)."},{"n":"Thorn Shot","t":"(Range 10) 5d4+5."}]},{"title":"Bloodied","items":[{"n":"At 50 HP","t":"Greenthumb gains magical bark, giving himself Heavy Armor."}]},{"title":"Last Stand","items":[{"n":"Greenthumb is dying!","t":"30 more damage and he dies. Until then, he chooses twice each turn."}]}],"hp":100}'::jsonb)
